export function parseCsv(text: string): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let field = "";
  let quoted = false;
  let lineHasContent = false;

  const endRow = () => {
    // A line with no characters at all is blank and dropped.
    if (lineHasContent) rows.push([...row, field]);
    row = [];
    field = "";
    lineHasContent = false;
  };

  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (quoted) {
      if (ch !== '"') field += ch;
      else if (text[i + 1] === '"') {
        field += '"';
        i++;
      } else quoted = false;
      continue;
    }
    if (ch === "\n" || (ch === "\r" && text[i + 1] === "\n")) {
      if (ch === "\r") i++;
      endRow();
      continue;
    }
    lineHasContent = true;
    if (ch === '"') quoted = true;
    else if (ch === ",") {
      row.push(field);
      field = "";
    } else field += ch;
  }
  endRow();
  return rows;
}
EOF
cat > src/money.ts <<'EOF'
const AMOUNT = /^(-?)(\d+|\d{1,3}(?:,\d{3})+)(?:\.(\d{1,2}))?$/;

export function parseAmount(raw: string): number {
  const match = AMOUNT.exec(raw);
  if (!match) throw new Error(`invalid amount: ${raw}`);
  const [, sign, integer, fraction = ""] = match;
  const cents = Number(integer.replaceAll(",", "")) * 100 + Number(fraction.padEnd(2, "0"));
  return sign ? -cents : cents;
}

export function formatCents(cents: number): string {
  const abs = Math.abs(cents);
  const sign = cents < 0 ? "-" : "";
  return `${sign}${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, "0")}`;
}
EOF
cat > src/report.ts <<'EOF'
import { parseCsv } from "./csv";
import { parseAmount } from "./money";

export type Summary = {
  totals: Map<string, number>;
  skipped: number;
};

export function summarize(csvText: string): Summary {
  const rows = parseCsv(csvText).slice(1);
  const totals = new Map<string, number>();
  let skipped = 0;
  for (const row of rows) {
    if (row.length !== 4) {
      skipped++;
      continue;
    }
    let cents: number;
    try {
      cents = parseAmount(row[3]);
    } catch {
      skipped++;
      continue;
    }
    const category = row[1].trim();
    totals.set(category, (totals.get(category) ?? 0) + cents);
  }
  return { totals, skipped };
}
EOF
cat > src/cli.ts <<'EOF'
import { formatCents } from "./money";
import { summarize } from "./report";

const path = process.argv[2];
if (!path) {
  console.error("usage: bun src/cli.ts <file.csv>");
  process.exit(2);
}

let text: string;
try {
  text = await Bun.file(path).text();
} catch {
  console.error(`error: cannot read ${path}`);
  process.exit(1);
}

const { totals, skipped } = summarize(text);
const sorted = [...totals].sort(([nameA, a], [nameB, b]) => b - a || (nameA < nameB ? -1 : nameA > nameB ? 1 : 0));
let grandTotal = 0;
for (const [category, cents] of sorted) {
  console.log(`${category}\t${formatCents(cents)}`);
  grandTotal += cents;
}
console.log(`TOTAL\t${formatCents(grandTotal)}`);
if (skipped > 0) console.error(`skipped: ${skipped}`);
EOF
